// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Tok {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address a, uint256 v) external { balanceOf[a] += v; }
    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; return true; }
    function transfer(address t, uint256 v) external returns (bool) {
        balanceOf[msg.sender] -= v; balanceOf[t] += v; return true;
    }
    function transferFrom(address f, address t, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) allowance[f][msg.sender] = a - v;
        balanceOf[f] -= v; balanceOf[t] += v; return true;
    }
}

contract InvMutTest is Test {
    C c;
    Tok tok;

    bytes32 constant ORDER_TYPE_HASH = keccak256(
        abi.encodePacked(
            "Order(",
            "address maker,",
            "bool isCall,",
            "bool isLong,",
            "address baseAsset,",
            "uint256 strike,",
            "uint256 premium,",
            "uint256 duration,",
            "uint256 expiration,",
            "uint256 nonce,",
            "address[] whitelist,",
            "address[] floorTokens,",
            "ERC20Asset[] erc20Assets,",
            "ERC721Asset[] erc721Assets",
            ")",
            "ERC20Asset(address token,uint256 tokenAmount)",
            "ERC721Asset(address token,uint256 tokenId)"
        )
    );
    bytes32 constant EMPTY_KECCAK = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    function setUp() public {
        c = new C("", 0, address(this));
        tok = new Tok();
    }

    function testFuzz_property(uint256 makerKey, address to, uint256 premium) public {
        makerKey = bound(makerKey, 1, type(uint256).max - 1);
        premium = bound(premium, 1, 1e18);
        vm.assume(to != address(0));

        address maker = vm.addr(makerKey);
        vm.assume(maker != to);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(tok),
            strike: 0,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 structHash = keccak256(
            abi.encode(
                ORDER_TYPE_HASH,
                order.maker,
                order.isCall,
                order.isLong,
                order.baseAsset,
                order.strike,
                order.premium,
                order.duration,
                order.expiration,
                order.nonce,
                EMPTY_KECCAK,
                EMPTY_KECCAK,
                EMPTY_KECCAK,
                EMPTY_KECCAK
            )
        );
        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", c.domainSeparatorV4(), structHash)
        );
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerKey, digest);
        bytes memory sig = abi.encodePacked(r, s, v);

        vm.startPrank(maker);
        tok.mint(maker, premium);
        tok.approve(address(c), premium);
        vm.stopPrank();

        c.fillOrder(order, sig, new uint256[](0));

        uint256 id = uint256(structHash == bytes32(0) ? bytes32(0) : keccak256("x")); // placeholder, recomputed below
        id = uint256(keccak256(abi.encodePacked(""))); // unused
        id = tokenIdOf(order);

        vm.prank(maker);
        c.transferFrom(maker, to, id);

        assertTrue(c.ownerOf(id) == to);
    }

    function tokenIdOf(C.Order memory order) internal view returns (uint256) {
        return uint256(c.hashOrder(order));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    DummyERC20 token;
    uint256 constant MAKER_KEY = 1;
    address maker;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new DummyERC20();
        maker = vm.addr(MAKER_KEY);
    }

    function testFuzz_property(
        address to,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration
    ) public {
        vm.assume(to != address(0));
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 10_000 days - 1);
        expiration = bound(expiration, block.timestamp + 1, type(uint256).max / 2);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(MAKER_KEY, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        bool ok = true;
        try c.fillOrder(order, sig, new uint256[](0)) {
            // minted both positions
        } catch {
            ok = false;
        }
        assertTrue(ok, "fillOrder failed");

        uint256 id = uint256(orderHash);
        vm.prank(maker);
        c.transferFrom(maker, to, id);

        // General rule: for every input, a token transfer keeps the sender's and
        // recipient's balances consistent (in C, balanceOf is constant for all
        // accounts). The buggy version omits the sender's decrement, so the
        // correspondence between the two accounts' balances breaks for some input.
        assertTrue(c.balanceOf(maker) == c.balanceOf(to), "balance correspondence broken");
    }
}

contract DummyERC20 {
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
